    private static Icons _icons = new(Svg);

    /// <summary>The kinds the set draws: the built-in ones and those the app and its libraries registered.</summary>
    public static IEnumerable<string> Names => Volatile.Read(ref _icons).ByKind.Keys;

    /// <summary>
    /// Adds icons to the set, each kind's SVG markup on a 24-pixel view box (the <c>Icon</c> control strokes it with its
    /// foreground, as Lucide's icons are drawn); a kind already in the set is replaced. The app's generated code registers
    /// the icon sets the app and its libraries declare (<see cref="Aioros.Icons.IconSetAttribute{T}"/>) when the host starts.
    /// </summary>
    public static void Register(IEnumerable<KeyValuePair<string, string>> icons)
    {
        ArgumentNullException.ThrowIfNull(icons);
        var added = icons.ToList();
        if (added.Count > 0)
        {
            ImmutableInterlocked.Update(ref _icons, static (current, more) => new Icons(current.ByKind.Concat(more).GroupBy(icon => icon.Key, StringComparer.Ordinal).Select(group => group.Last())), added);
        }
    }

    public static string Markup(string? kind) => kind is not null && Volatile.Read(ref _icons).ByKind.TryGetValue(kind, out var svg) ? svg : string.Empty;

    /// <summary>The icon's markup as UTF-8 bytes, encoded once.</summary>
    public static ReadOnlySpan<byte> Utf8(string? kind) => kind is not null && Volatile.Read(ref _icons).Encoded.TryGetValue(kind, out var svg) ? svg : [];

    private sealed class Icons(IEnumerable<KeyValuePair<string, string>> icons)
    {
        public FrozenDictionary<string, string> ByKind { get; } = icons.ToFrozenDictionary(StringComparer.Ordinal);

        public FrozenDictionary<string, byte[]> Encoded { get; } = icons.ToFrozenDictionary(static icon => icon.Key, static icon => System.Text.Encoding.UTF8.GetBytes(icon.Value), StringComparer.Ordinal);
    }
}
